// Category B — no headless primitive, and the behaviour is arrangement only, so this owns
// everything (component-contract.md § 3).
//
// A row of related actions. It is NOT `Stack` with a different name: it does three things Stack's
// props cannot express, and that `Dialog` and `Drawer` both need.
//
//   1. `column-reverse` on a narrow screen, so the PRIMARY action rises to the top while staying
//      last in the DOM for tab order. `Stack`'s direction is `"row" | "column"`; it has no reverse.
//   2. `layout="center"` lays the actions out as equal grid columns, and `layout="fill"` as a hugging
//      aside action beside a primary that fills the row. `Stack` is flex only.
//   3. The gap is a Cmp token this component owns, not a Sys rung its caller picks — the actions
//      are always the innermost level of their container, and Dialog and Drawer had already
//      converged on the same rung independently.
//
// One copy rather than two, for the reason `figma-projection.md` records for Toolbar: "retuning one
// silently desynced the other".
import type { ReactNode, Ref } from "react";
import "./ButtonGroup.css";

/** How the actions are placed. */
export type ButtonGroupLayout = "end" | "center" | "stack" | "fill";

export interface ButtonGroupProps {
  /**
   * Action placement. `end` right-aligns and lets the buttons hug; `center` splits the width
   * evenly between them; `stack` keeps the full-width column at every size; `fill` keeps one row at
   * every size, an aside action (reset, back) hugging its label and the primary filling the rest.
   * `fill` is a PAIR: its tracks alternate hug and fill, so a third action lands out of step.
   * @default "end"
   */
  layout?: ButtonGroupLayout;
  /** The actions, in DOM order. The last one is the primary — it renders first on a narrow screen. */
  children?: ReactNode;
  /** Additional class (optional). sd-button-group is always preserved. */
  className?: string;
  /** Forwarded to the underlying <div> DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ButtonGroup({ layout = "end", children, className, ref }: ButtonGroupProps) {
  return (
    <div
      ref={ref}
      data-layout={layout}
      className={className ? `sd-button-group ${className}` : "sd-button-group"}
    >
      {children}
    </div>
  );
}

/* ButtonGroup.css — .sd-button-group
   A row of related actions, the one copy of the rules `Dialog.css` and `Drawer.css` would otherwise
   each carry. */
.sd-button-group {
  display: flex;
  flex-direction: column-reverse;
  align-items: stretch;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--sd-button-group-gap);
}

.sd-button-group[data-layout="center"] {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
}

/* fill: one row at every size, the aside action hugging its label and the primary (last) taking the
   rest. Grid tracks rather than a grow on the last child, which only a child selector could reach. */
.sd-button-group[data-layout="fill"] {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: max-content minmax(0, 1fr);
}

.sd-button-group[data-layout="stack"] {
  flex-direction: column-reverse;
  align-items: stretch;
}

/* mobile: the default (end) actions stack full-width, primary (last child) on top.
   mobile-first (naming-convention § Modes): the stacked, full-width action list is the BASE —
   on a narrow panel a side-by-side row would squeeze the buttons — and the `medium` step restores
   the right-aligned row. Never a `max-width` query: that would author desktop as the base and
   invert the ladder every other responsive rule in the system follows. */
@media (min-width: 768px) {
  .sd-button-group[data-layout="end"] {
    flex-direction: row;
    align-items: initial;
  }
}
